cssCode:
.dock-container {
  display: flex; gap: 15px; padding: 15px 25px;
  background: rgba(255,255,255,0.05); backdrop-filter: blur(20px);
  border-radius: 25px; border: 1px solid rgba(255,255,255,0.1);
  box-shadow: 0 20px 40px rgba(0,0,0,0.5);
}
.dock-item {
  width: 50px; height: 50px; background: rgba(255,255,255,0.1);
  border-radius: 15px; display: flex; align-items: center; justify-content: center;
  font-size: 24px; cursor: pointer;
  transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.dock-item:hover, .dock-item:active {
  transform: translateY(-15px) scale(1.3);
  background: #6c63ff; color: #fff;
  box-shadow: 0 10px 20px rgba(108, 99, 255, 0.5);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:flex-end;justify-content:center;padding-bottom:50px;background:transparent;';

const dock = document.createElement('div');
dock.className = 'dock-container';

const icons = ['🏠', '🔍', '💬', '⚙️'];
icons.forEach(icon => {
  const item = document.createElement('div');
  item.className = 'dock-item';
  item.innerText = icon;
  dock.appendChild(item);
});
c.appendChild(dock);
